import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";
import "./cambiarcontrasena.css";

export default function CambiarContrasena() {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const navigate = useNavigate();

  const handleChangePassword = async (e) => {
    e.preventDefault();

    const token = localStorage.getItem("token");

    if (!token) {
      Swal.fire({
        icon: "warning",
        title: "Sesión requerida",
        text: "Debes iniciar sesión para cambiar tu contraseña",
        confirmButtonColor: "#7b2ff7"
      });
      navigate("/login");
      return;
    }

    if (!currentPassword || !newPassword || !confirmPassword) {
      Swal.fire({
        icon: "warning",
        title: "Campos incompletos",
        text: "Por favor completa todos los campos",
        confirmButtonColor: "#7b2ff7"
      });
      return;
    }

    if (newPassword.length < 8) {
      Swal.fire({
        icon: "warning",
        title: "Contraseña insegura",
        text: "La nueva contraseña debe tener al menos 8 caracteres",
        confirmButtonColor: "#7b2ff7"
      });
      return;
    }

    if (newPassword !== confirmPassword) {
      Swal.fire({
        icon: "warning",
        title: "Error",
        text: "La nueva contraseña y la confirmación no coinciden",
        confirmButtonColor: "#7b2ff7"
      });
      return;
    }

    try {
      const response = await fetch(
        "https://backend-cozyhome.onrender.com/api/clients/change-password",
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`
          },
          body: JSON.stringify({
            currentPassword,
            newPassword,
            confirmPassword
          })
        }
      );

      const data = await response.json();

      if (!response.ok) {
        Swal.fire({
          icon: "error",
          title: "No se pudo cambiar la contraseña",
          text: data.message || data.error || "Ocurrió un error",
          confirmButtonColor: "#7b2ff7"
        });
        return;
      }

      Swal.fire({
        icon: "success",
        title: "Contraseña actualizada",
        text: "Tu contraseña fue cambiada correctamente. Debes volver a iniciar sesión.",
        confirmButtonColor: "#7b2ff7"
      });

      localStorage.removeItem("token");
      localStorage.removeItem("user");
      window.dispatchEvent(new Event("userChanged"));

      navigate("/login");
    } catch (error) {
      console.error("Error al cambiar contraseña:", error);
      Swal.fire({
        icon: "error",
        title: "Error de conexión",
        text: "No se pudo conectar con el servidor",
        confirmButtonColor: "#7b2ff7"
      });
    }
  };

  return (
    <div className="cambiar-contrasena-page">
      <div className="cambiar-contrasena-container">
        <div className="cambiar-contrasena-header">
          <h2>Cambiar contraseña</h2>
          <p>Actualiza tu contraseña de forma segura</p>
        </div>

        <form className="cambiar-contrasena-form" onSubmit={handleChangePassword}>
          <div className="form-group">
            <label>Contraseña actual</label>
            <input
              type="password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              placeholder="Ingresa tu contraseña actual"
              required
            />
          </div>

          <div className="form-group">
            <label>Nueva contraseña</label>
            <input
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              placeholder="Mínimo 8 caracteres"
              required
            />
          </div>

          <div className="form-group">
            <label>Confirmar nueva contraseña</label>
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Repite la nueva contraseña"
              required
            />
          </div>

          <button type="submit" className="btn-cambiar-contrasena">
            Actualizar contraseña
          </button>
        </form>
      </div>
    </div>
  );
}
